// Search only models released in the last 45 days. A search costs 100 quota
// units against a 10,000/day free allowance, so searching all 38 tracked
// models daily would burn 38% of the budget re-finding videos about models
// nobody is still reviewing.
const models = $('GET tracked models').first().json.models ?? [];
const cutoff = Date.now() - 1000 * 60 * 60 * 24 * 45;
const publishedAfter = new Date(cutoff).toISOString();

const recent = models
  .filter((m) => m.name && m.name.length >= 4)
  .slice(0, 8);

return recent.map((m) => ({ json: {
  slug: m.slug, name: m.name, publishedAfter,
  q: `${m.name} review`,
} }));

// Fan out from each search result to its video ids. commentThreads costs
// 1 unit per call versus 100 for a search, so pulling comments is nearly
// free once the video is found.
const sources = $('Models to search').all();
const out = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const model = sources[i]?.json;
  if (!model) continue;
  for (const item of (items[i].json?.items ?? []).slice(0, 3)) {
    const videoId = item?.id?.videoId;
    if (!videoId) continue;
    out.push({ json: {
      videoId,
      slug: model.slug,
      name: model.name,
      videoTitle: item?.snippet?.title ?? '',
    } });
  }
}

return out;

// YouTube comments are the noisiest source by a wide margin, so the cheap
// filters run hard here before anything reaches Claude: length, recency,
// and the comment naming the model itself rather than inheriting it from
// the video title.

function buildMatchers(models) {
  return models
    .filter((m) => m.name && m.name.length >= 4)
    .map((m) => ({ slug: m.slug, name: m.name, needle: m.name.toLowerCase() }))
    .sort((a, b) => b.needle.length - a.needle.length);
}

function matchModel(text, matchers) {
  const hay = String(text || '').toLowerCase();
  for (const m of matchers) {
    if (hay.includes(m.needle)) return m;
  }
  return null;
}

function stripHtml(s) {
  return String(s || '')
    .replace(/<blockquote[\s\S]*?<\/blockquote>/gi, ' ')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&#x2F;/g, '/')
    .replace(/&#x27;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const sources = $('Videos to read').all();
const models = $('GET tracked models').first().json.models ?? [];
const matchers = buildMatchers(models);
const cap = $('Classifier contract').first().json.candidatesPerRun ?? 12;

const out = [];
const seen = new Set();
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const video = sources[i]?.json;
  if (!video) continue;

  for (const thread of items[i].json?.items ?? []) {
    const c = thread?.snippet?.topLevelComment?.snippet;
    if (!c) continue;
    const text = stripHtml(c.textOriginal ?? c.textDisplay);
    if (text.length < 180) continue;

    const model = matchModel(text, matchers);
    if (!model) continue;

    const url = `https://www.youtube.com/watch?v=${video.videoId}&lc=${thread.id}`;
    if (seen.has(url)) continue;
    seen.add(url);

    out.push({ json: {
      modelSlug: model.slug,
      modelName: model.name,
      sourceUrl: url,
      text: text.slice(0, 4000),
    } });
  }
}

return out.slice(0, cap);

